// src/screens/home/app.tsx
import { useCallback, useEffect, useState } from "react";
import { AppShell } from "@lophn/ui/layout";
import { Button } from "@lophn/ui/primitives";
import { appBridge } from "@lophn/app-ui";
import { t } from "../../wording/t.ts";
import styles from "./app.module.css";

const DAY = 86_400_000;

interface Row {
  schedule_id: string;
  title: string;
  start: number;
  original_start: number;
  status: "planned" | "complete" | "skipped" | "held" | "rescheduled";
}
interface Ev {
  id: string;
  title: string;
  start: number;
}
type View = "month" | "week";

const utcDay = (ms: number) => Math.floor(ms / DAY) * DAY;
const fmt = (ms: number, options: Intl.DateTimeFormatOptions) =>
  new Intl.DateTimeFormat(undefined, { timeZone: "UTC", ...options }).format(
    ms,
  );

// 보이는 칸의 첫 날(월요일 시작)과 칸 수.
function span(view: View, anchor: number): { first: number; days: number } {
  const monday = (d: number) => d - ((new Date(d).getUTCDay() + 6) % 7) * DAY;
  if (view === "week") return { first: monday(utcDay(anchor)), days: 7 };
  const a = new Date(anchor);
  const first = monday(Date.UTC(a.getUTCFullYear(), a.getUTCMonth(), 1));
  const end = Date.UTC(a.getUTCFullYear(), a.getUTCMonth() + 1, 1);
  return { first, days: Math.ceil((end - first) / DAY / 7) * 7 };
}

export function App() {
  const [view, setView] = useState<View>("month");
  const [anchor, setAnchor] = useState(() => Date.now());
  const [rows, setRows] = useState<Row[]>([]);
  const [events, setEvents] = useState<Ev[]>([]);
  const [error, setError] = useState<"load" | "act" | null>(null);
  const [picked, setPicked] = useState<Row | null>(null);
  const { first, days } = span(view, anchor);

  const load = useCallback(async () => {
    const bridge = appBridge();
    if (!bridge) return setError("load");
    try {
      const range = { from: first, to: first + days * DAY };
      const [occ, evs] = await Promise.all([
        bridge.callTool("schedule.occurrences", range) as Promise<
          { rows: Row[] }
        >,
        bridge.callTool("event.list", range) as Promise<{ events: Ev[] }>,
      ]);
      setRows(occ.rows);
      setEvents(evs.events);
      setError(null);
    } catch {
      setError("load");
    }
  }, [first, days]);
  useEffect(() => {
    load();
  }, [load]);

  const act = async (action: "complete" | "reschedule" | "skip" | "hold") => {
    if (!picked) return;
    try {
      await appBridge()?.callTool("occurrence.act", {
        schedule_id: picked.schedule_id,
        original_start: picked.original_start,
        action,
        ...(action === "reschedule" ? { new_start: picked.start + DAY } : {}),
      });
      setPicked(null);
      await load();
    } catch {
      setError("act");
    }
  };

  const step = (dir: number) => {
    const a = new Date(anchor);
    setAnchor(
      view === "week"
        ? anchor + dir * 7 * DAY
        : Date.UTC(a.getUTCFullYear(), a.getUTCMonth() + dir, 1),
    );
  };
  const month = new Date(anchor).getUTCMonth();
  const label = view === "month"
    ? fmt(anchor, { year: "numeric", month: "long" })
    : `${fmt(first, { month: "short", day: "numeric" })} – ${
      fmt(first + 6 * DAY, { month: "short", day: "numeric" })
    }`;

  return (
    <AppShell title={t("common.title.app")}>
      <div className={styles.bar}>
        <Button size="sm" onClick={() => step(-1)}>
          {t("home.button.previous")}
        </Button>
        <Button size="sm" onClick={() => setAnchor(Date.now())}>
          {t("home.button.today")}
        </Button>
        <Button size="sm" onClick={() => step(1)}>{t("home.button.next")}</Button>
        <span className={styles.range}>{label}</span>
        <Button
          size="sm"
          variant={view === "month" ? "primary" : "secondary"}
          onClick={() => setView("month")}
        >
          {t("home.view.month")}
        </Button>
        <Button
          size="sm"
          variant={view === "week" ? "primary" : "secondary"}
          onClick={() => setView("week")}
        >
          {t("home.view.week")}
        </Button>
      </div>
      {error && (
        <p className={styles.error}>
          {t(error === "load" ? "home.error.load" : "home.error.act")}
        </p>
      )}
      <div className={styles.grid}>
        {Array.from(
          { length: 7 },
          (_, i) => (
            <div key={i} className={styles.head}>
              {fmt(first + i * DAY, { weekday: "short" })}
            </div>
          ),
        )}
        {Array.from({ length: days }, (_, i) => {
          const day = first + i * DAY;
          const outside = view === "month" &&
            new Date(day).getUTCMonth() !== month;
          const inDay = (s: number) => s >= day && s < day + DAY;
          return (
            <div
              key={day}
              className={`${view === "week" ? styles.cellWeek : styles.cell} ${
                outside ? styles.outside : ""
              }`}
            >
              <span className={styles.day}>{fmt(day, { day: "numeric" })}</span>
              {events.filter((e) => inDay(e.start)).map((e) => (
                <span key={e.id} className={`${styles.item} ${styles.event}`}>
                  {fmt(e.start, { hour: "2-digit", minute: "2-digit" })}{" "}
                  {e.title}
                </span>
              ))}
              {rows.filter((r) => inDay(r.start)).map((r) => (
                <button
                  key={`${r.schedule_id}:${r.original_start}`}
                  type="button"
                  className={`${styles.item} ${styles[r.status] ?? ""}`}
                  onClick={() => setPicked(r)}
                >
                  {fmt(r.start, { hour: "2-digit", minute: "2-digit" })}{" "}
                  {r.title}
                </button>
              ))}
            </div>
          );
        })}
      </div>
      {picked && (
        <div className={styles.detail}>
          <span>
            {t("home.detail.title", {
              title: picked.title,
              status: t(`home.label.${picked.status}`),
            })}
          </span>
          <Button size="sm" onClick={() => act("complete")}>
            {t("home.button.complete")}
          </Button>
          <Button size="sm" onClick={() => act("reschedule")}>
            {t("home.button.reschedule")}
          </Button>
          <Button size="sm" onClick={() => act("skip")}>
            {t("home.button.skip")}
          </Button>
          <Button size="sm" onClick={() => act("hold")}>
            {t("home.button.hold")}
          </Button>
          <Button size="sm" variant="ghost" onClick={() => setPicked(null)}>
            {t("home.button.close")}
          </Button>
        </div>
      )}
    </AppShell>
  );
}


